    /// <summary>
    /// Middleware для логирования медленных HTTP-запросов.
    /// Замеряет время обработки запроса и записывает в лог, если оно превышает заданный порог.
    /// </summary>
    public class SlowRequestLoggingMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly ILogger<SlowRequestLoggingMiddleware> _logger;
        private readonly int _thresholdMilliseconds;

        /// <summary>
        /// Инициализирует новый экземпляр middleware.
        /// </summary>
        /// <param name="next">Следующий обработчик в цепочке middleware.</param>
        /// <param name="logger">Логгер для записи сообщений о медленных запросах.</param>
        /// <param name="thresholdMilliseconds">Порог времени (в миллисекундах), превышение которого считается медленным запросом.</param>
        public SlowRequestLoggingMiddleware(
            RequestDelegate next,
            ILogger<SlowRequestLoggingMiddleware> logger,
            int thresholdMilliseconds = 500)
        {
            _next = next ?? throw new ArgumentNullException(nameof(next));
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
            _thresholdMilliseconds = thresholdMilliseconds;
        }

        /// <summary>
        /// Обрабатывает входящий HTTP-запрос: замеряет время выполнения и логирует, если запрос оказался медленным.
        /// </summary>
        /// <param name="context">Контекст HTTP-запроса.</param>
        /// <returns>Задача, представляющая результат обработки запроса.</returns>
        public async Task InvokeAsync(HttpContext context)
        {
            // Создаём таймер для измерения времени обработки запроса.
            // Stopwatch обеспечивает высокую точность измерений.
            var stopwatch = Stopwatch.StartNew();

            try
            {
                // Передаём управление следующему middleware или конечному обработчику (контроллеру).
                await _next.Invoke(context);
            }
            finally
            {
                // Останавливаем таймер независимо от того, завершился ли запрос успешно или с исключением.
                stopwatch.Stop();

                // Получаем длительность запроса в миллисекундах.
                long elapsedMilliseconds = stopwatch.ElapsedMilliseconds;

                // Проверяем, превысил ли запрос установленный порог.
                if (elapsedMilliseconds >= _thresholdMilliseconds)
                {
                    // Формируем сообщение с деталями медленного запроса.
                    // Включаем метод, путь, длительность и статус ответа для удобства диагностики.
                    string message = $"Медленный запрос: {context.Request.Method} {context.Request.Path} " +
                                     $"занимает {elapsedMilliseconds} мс (порог: {_thresholdMilliseconds} мс), " +
                                     $"статус: {(int)context.Response.StatusCode}";

                    // Записываем предупреждение в лог.
                    // Используем LogLevel.Warning, так как медленные запросы — это потенциальная проблема производительности.
                    _logger.LogWarning(message);
