// WorkerPool — пул воркеров, обрабатывающих задачи из канала с ограничением параллелизма.
// Пул использует фиксированное количество горутины-воркеров, которые берут задачи
// из общего канала и выполняют их последовательно внутри каждой горутины.
type WorkerPool struct {
	taskChan chan Task // Канал для передачи задач от отправителя к воркерам
	numWorkers int     // Количество воркеров в пуле
	wg       sync.WaitGroup // WaitGroup для ожидания завершения всех воркеров
	ctx      context.Context // Контекст для управления жизненным циклом пула
	cancel   context.CancelFunc // Функция отмены контекста
}

// NewWorkerPool создаёт новый экземпляр WorkerPool с указанным количеством воркеров.
// numWorkers — количество горутины-воркеров, которые будут одновременно обрабатывать задачи.
// Если numWorkers <= 0, будет использовано значение по умолчанию (1).
func NewWorkerPool(numWorkers int) *WorkerPool {
	if numWorkers <= 0 {
		numWorkers = 1
	}

	// Создаём канал задач с буфером, чтобы избежать блокировки отправителя,
	// пока все воркеры заняты. Размер буфера равен количеству воркеров,
	// что позволяет накапливать задачи без потери производительности.
	taskChan := make(chan Task, numWorkers)

	// Создаём контекст с возможностью отмены.
	// Это позволит корректно остановить все воркеры при необходимости.
	ctx, cancel := context.WithCancel(context.Background())

	return &WorkerPool{
		taskChan:   taskChan,
		numWorkers: numWorkers,
		ctx:        ctx,
		cancel:     cancel,
	}
}

