 * Валидатор ИНН (идентификационный номер налогоплательщика) и ОГРН
 * (основной государственный регистрационный номер).
 *
 * Реализует проверку по официальным алгоритмам контрольных цифр:
 * - ИНН для юридических лиц (10 цифр) — модуль 11 с весами [2,4,10,3,5,9,4,6,8]
 * - ИНН для физических лиц (12 цифр) — два этапа: первые 9 цифр проверяются
 *   как ИНН юрлица, затем добавляется 10-я цифра и проверяется весь 10-значный
 *   номер тем же алгоритмом.
 * - ОГРН (13 цифр) — модуль 11 с весами [2,4,10,3,5,9,7,2,4,10,3,5].
 */
object Validator {

    /**
     * Проверяет корректность ИНН юридического лица (10 цифр).
     *
     * Алгоритм:
     * 1. Первые 9 цифр умножаются на соответствующие веса [2,4,10,3,5,9,4,6,8].
     * 2. Сумма произведений делится на 11.
     * 3. Остаток от деления сравнивается с 10-й (контрольной) цифрой.
     *    Если остаток равен 10, то контрольная цифра должна быть 0.
     *
     * @param inn Строка из 10 цифр без пробелов и дефисов.
     * @return true, если ИНН валиден; false — иначе.
     */
    fun validateInnLegalEntity(inn: String): Boolean {
        // Базовая проверка: длина ровно 10 символов
        if (inn.length != 10) {
            return false
        }

        // Все символы должны быть цифрами
        if (!inn.all { it.isDigit() }) {
            return false
        }

        // Веса для первых 9 цифр ИНН юрлица
        val weights = intArrayOf(2, 4, 10, 3, 5, 9, 4, 6, 8)

        // Вычисляем сумму произведений первых 9 цифр на их веса
        var sum = 0
        for (i in 0 until 9) {
            sum += (inn[i] - '0') * weights[i]
        }

        // Контрольная цифра — это остаток от деления суммы на 11
        // Если остаток равен 10, то контрольная цифра считается равной 0
        val controlDigit = if (sum % 11 == 10) 0 else sum % 11

        // Сравниваем вычисленную контрольную цифру с последней цифрой ИНН
        return (inn[9] - '0') == controlDigit
    }

