/**
 * Кэш с вытеснением по давности использования (LRU — Least Recently Used)
 * и ограничением по памяти.
 *
 * <p>Реализация использует связный список для хранения элементов в порядке
 * их последнего использования, а хеш-таблицу для быстрого доступа к элементам
 * по ключу. При добавлении нового элемента или обращении к существующему
 * он перемещается в начало списка (считается "самым свежим"). Если размер
 * кэша превышает заданный лимит, самый старый элемент (находится в конце
 * списка) удаляется.</p>
 *
 * <p>Класс не является потокобезопасным. Для многопоточного использования
 * необходимо обеспечить внешнюю синхронизацию.</p>
 *
 * @param <K> тип ключа
 * @param <V> тип значения
 */
public class LRUCache<K, V> {

    /**
     * Максимальное количество элементов, которое может храниться в кэше.
     * При превышении этого значения самый старый элемент будет удалён.
     */
    private final int capacity;

    /**
     * Хеш-таблица для быстрого поиска элемента по ключу.
     * Ключ — это объект типа K, значение — ссылка на узел двусвязного списка.
     */
    private final Map<K, Node<K, V>> map;

    /**
     * Голова двусвязного списка. Указывает на самый недавно использованный элемент.
     */
    private Node<K, V> head;

    /**
     * Хвост двусвязного списка. Указывает на самый давно использованный элемент.
     */
    private Node<K, V> tail;

    /**
     * Текущее количество элементов в кэше.
     */
    private int size;

    /**
     * Создаёт новый экземпляр LRU-кэша с указанным максимальным размером.
     *
     * @param capacity максимальное количество элементов в кэше. Должно быть > 0.
     * @throws IllegalArgumentException если capacity <= 0.
     */
    public LRUCache(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Capacity must be positive: " + capacity);
        }
        this.capacity = capacity;
        this.map = new HashMap<>();
        this.size = 0;
        // Инициализируем dummy-узлы для упрощения операций вставки и удаления
        // без проверки на null. Head всегда указывает на первый реальный узел,
        // Tail — на последний.
        this.head = new Node<>(null, null);
        this.tail = new Node<>(null, null);
        head.next = tail;
        tail.prev = head;
    }

