/**
 * Функция debounce (дебаунс) — откладывает выполнение переданной функции
 * до тех пор, пока не перестанут приходить вызовы в течение заданного времени.
 *
 * @param fn - функция, которую нужно обернуть в дебаунс
 * @param ms - время ожидания в миллисекундах
 * @returns новая функция с теми же параметрами, что и исходная
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Она используется для отмены предыдущего запланированного вызова.
  let timer: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и исходная.
  return (...args: Parameters<T>) => {
    // Если уже есть активный таймер, отменяем его.
    // Это гарантирует, что функция выполнится только после последнего вызова.
    if (timer) clearTimeout(timer);

    // Запускаем новый таймер на указанное количество миллисекунд.
    // По истечении времени будет вызвана исходная функция с сохранёнными аргументами.
    timer = setTimeout(() => fn(...args), ms);
  };
}
```

