/// Вычисляет медиану (среднее значение) элементов вектора `f64`.
///
/// # Назначение
/// Функция находит медиану набора чисел, представленных в виде вектора `Vec<f64>`.
/// Медиана определяется как среднее арифметическое двух центральных элементов при чётном количестве элементов
/// или как единственный центральный элемент при нечётном количестве.
///
/// # Параметры
/// * `v` — ссылка на изменяемый вектор `Vec<f64>`, содержащий значения, для которых вычисляется медиана.
///   Вектор будет отсортирован по возрастанию перед вычислением медианы.
///
/// # Возвращаемое значение
/// * `Some(f64)` — медиана элементов вектора, если вектор непустой.
/// * `None` — если вектор пуст.
///
/// # Исключения и граничные случаи
/// * Если вектор пуст, функция возвращает `None`.
/// * Если в векторе есть элементы, равные `NaN` (Not a Number), поведение функции не определено,
///   так как `partial_cmp` вернёт `None` для сравнения с `NaN`, и вызов `unwrap()` приведёт к панике.
///   Рекомендуется убедиться, что все элементы вектора являются конечными числами (`is_finite()`).
/// * Функция изменяет исходный вектор: он будет отсортирован по возрастанию.
/// * Для вектора из одного элемента возвращается этот элемент.
/// * Для вектора из двух элементов возвращается их среднее арифметическое.
///
/// # Примеры
/// ```
/// use std::vec;
///
/// let mut v = vec![3.0, 1.0, 2.0];
/// assert_eq!(median(&mut v), Some(2.0));
///
/// let mut v_even = vec![4.0, 1.0, 3.0, 2.0];
/// assert_eq!(median(&mut v_even), Some(2.5));
///
/// let mut empty = vec![];
/// assert_eq!(median(&mut empty), None);
/// ```
pub fn median(v: &mut Vec<f64>) -> Option<f64> {
    if v.is_empty() { return None; }
    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let m = v.len() / 2;
    Some(if v.len() % 2 == 0 { (v[m - 1] + v[m]) / 2.0 } else { v[m] })
}
```

